/*
 * GameDatabase.cs
 * ----------------------------------------------------------------------------
 * The content of the game as Unity data. Every value here is generated by the
 * editor importer (DataImporter.cs) from Data/Source/source-data.json, which is
 * itself exported from the web game's GameData.js and Scenes.js. Gameplay code
 * reads content only through this asset.
 * ----------------------------------------------------------------------------
 */

using System;
using System.Collections.Generic;
using UnityEngine;

namespace SpiceTrip.Data
{
    [Serializable]
    public class ItemDef
    {
        public string id;
        public string name;
        public string type;          // consumable | quest | relic | currency
        public string desc;
        public int heal;
        public int mana;
        public float fireDamage;     // relic passive
    }

    [Serializable]
    public class BossDef
    {
        public string id;
        public string name;
        public string img;           // file name in StreamingAssets/assets
        public int hp;
        public string color;         // CSS hex
        public float cx, cy;         // position on the path image (fractions)
        public Rect portraitRect;    // normalised crop (top-left origin) used in the arena
    }

    [Serializable]
    public class CharacterDef
    {
        public string id;
        public string name;
        public string img;           // null/empty → procedural hero
        public bool empty;           // "Coming soon" placeholder
        public Rect portraitRect;
    }

    [Serializable]
    public class ShopEntry
    {
        public string id;
        public int price;
    }

    [CreateAssetMenu(menuName = "Spice Trip/Game Database")]
    public class GameDatabase : ScriptableObject
    {
        public List<ItemDef> items = new List<ItemDef>();
        public List<BossDef> bosses = new List<BossDef>();
        public List<CharacterDef> characters = new List<CharacterDef>();
        public List<ShopEntry> shopStock = new List<ShopEntry>();
        public List<string> tips = new List<string>();
        public List<string> prophecy = new List<string>();
        public int hubStartingGold = 1450;
        public BattleTuning battle = new BattleTuning();
        public LoomTuning loom = new LoomTuning();

        public const string ResourcePath = "Data/GameDatabase";

        static GameDatabase _instance;
        public static GameDatabase Instance
        {
            get
            {
                if (_instance == null) _instance = Resources.Load<GameDatabase>(ResourcePath);
                return _instance;
            }
        }

        public ItemDef Item(string id) => items.Find(i => i.id == id);
        public BossDef Boss(string id) => bosses.Find(b => b.id == id);
        public CharacterDef Character(string id) => characters.Find(c => c.id == id);
    }
}
